parameters.jsCode:
const response = $input.item.json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(response);
} catch (e) {
  throw new Error('STRUCTURAL_ERROR: Agent 1 did not return valid JSON.');
}

if (!parsed.daily_timeline || typeof parsed.daily_timeline !== 'object') {
  throw new Error('STRUCTURAL_ERROR: Agent 1 output is missing or invalid `daily_timeline`. Must be an object or array.');
}

// 1. Strict timeframe validation (Gatekeeper requirement)
const brief = $node['Scope Resolve'].json.body || '';
const daysMatch = brief.match(/(\d+)\s*(days|ngày)/i);
if (daysMatch) {
  const expectedDays = parseInt(daysMatch[1], 10);
  const timelineKeys = Object.keys(parsed.daily_timeline);
  const timelineLength = Array.isArray(parsed.daily_timeline) ? parsed.daily_timeline.length : timelineKeys.length;

  if (timelineLength !== expectedDays) {
    throw new Error(`VALIDATION_ERROR: Agent 1 output failed strict constraint. Expected exactly ${expectedDays} days based on brief, but got ${timelineLength} days.`);
  }
}

// 2. Strict no-ads validation (Gatekeeper requirement)
if (brief.toLowerCase().includes('no ads') || brief.toLowerCase().includes('không chạy ads') || brief.toLowerCase().includes('không ads') || brief.toLowerCase().includes('organic')) {
  if (parsed.uses_ads !== false) {
    throw new Error('VALIDATION_ERROR: Agent 1 output failed strict constraint. Strategy uses ads despite brief requesting no ads. Property `uses_ads` must be false.');
  }
}

return $input.item;

